		seasonalBins(s, step).forEach(function (b) {
			if (b[0] !== part) return;
			var value = reduce(col.filterDate(b[2], b[3]), red);
			imgs.push(ee.Image.constant(b[1]).toFloat().rename('t').updateMask(value.mask()).addBands(value));
		});
